//! Genuine `sdk/lib/rtl/nls.c` vs rtl-strings' table-driven port (`cabi/nls_tables.rs`,
//! what the kernel and ntdll run), both loaded with REAL code pages generated by the
//! tree's own txt2nls (build.rs): the shipping pair (ANSI 1252, OEM 437) and a double-byte
//! one (932 for both), which is the only way to reach the multi-byte branches.
//!
//! Every WCHAR and every byte goes through the case helpers; the converters get seeded
//! strings drawn from the ranges where the tables differ (ASCII, Latin-1, the 0x80-0x9F
//! CP1252 specials, box drawing, kana/kanji, unmapped BMP), at every output size up to
//! past the input, with and without ResultSize, into canary-filled buffers.

#![allow(non_snake_case, non_upper_case_globals, non_camel_case_types, dead_code)]

mod port {
    include!(concat!(env!("OUT_DIR"), "/nls_tables_port.rs"));
}
use port::{CPTABLEINFO, NLSTABLEINFO};

extern "C" {
    fn nref_RtlInitNlsTables(a: *mut u16, o: *mut u16, c: *mut u16, t: *mut NLSTABLEINFO);
    fn nref_RtlResetRtlTranslations(t: *mut NLSTABLEINFO);
    fn nref_RtlpUpcaseUnicodeChar(c: u16) -> u16;
    fn nref_RtlpDowncaseUnicodeChar(c: u16) -> u16;
    fn nref_RtlUpcaseUnicodeChar(c: u16) -> u16;
    fn nref_RtlDowncaseUnicodeChar(c: u16) -> u16;
    fn nref_RtlUpperChar(c: u8) -> u8;
    fn nref_RtlGetDefaultCodePage(a: *mut u16, o: *mut u16);
    fn nref_RtlMultiByteToUnicodeN(u: *mut u16, us: u32, rs: *mut u32, mb: *const u8, mbs: u32) -> i32;
    fn nref_RtlOemToUnicodeN(u: *mut u16, us: u32, rs: *mut u32, mb: *const u8, mbs: u32) -> i32;
    fn nref_RtlMultiByteToUnicodeSize(us: *mut u32, mb: *const u8, mbs: u32) -> i32;
    fn nref_RtlUnicodeToMultiByteN(mb: *mut u8, mbs: u32, rs: *mut u32, u: *const u16, us: u32) -> i32;
    fn nref_RtlUnicodeToOemN(mb: *mut u8, mbs: u32, rs: *mut u32, u: *const u16, us: u32) -> i32;
    fn nref_RtlUpcaseUnicodeToMultiByteN(mb: *mut u8, mbs: u32, rs: *mut u32, u: *const u16, us: u32) -> i32;
    fn nref_RtlUpcaseUnicodeToOemN(mb: *mut u8, mbs: u32, rs: *mut u32, u: *const u16, us: u32) -> i32;
    fn nref_RtlUnicodeToMultiByteSize(mbs: *mut u32, u: *const u16, us: u32) -> i32;
    fn nref_RtlCustomCPToUnicodeN(cp: *mut CPTABLEINFO, u: *mut u16, us: u32, rs: *mut u32, s: *const i8, ss: u32) -> i32;
    fn nref_RtlUnicodeToCustomCPN(cp: *mut CPTABLEINFO, s: *mut i8, ss: u32, rs: *mut u32, u: *mut u16, us: u32) -> i32;
    fn nref_RtlUpcaseUnicodeToCustomCPN(cp: *mut CPTABLEINFO, s: *mut i8, ss: u32, rs: *mut u32, u: *mut u16, us: u32) -> i32;
}

/// An NLS file as the kernel maps it: 2-byte aligned, never moved, never freed.
fn table(path: &str) -> *mut u16 {
    let bytes = std::fs::read(path).unwrap_or_else(|e| panic!("{path}: {e}"));
    let mut words = vec![0u16; bytes.len().div_ceil(2)];
    for (i, b) in bytes.iter().enumerate() {
        words[i / 2] |= (*b as u16) << ((i % 2) * 8);
    }
    Box::leak(words.into_boxed_slice()).as_mut_ptr()
}

fn zeroed<T>() -> T {
    unsafe { std::mem::zeroed() }
}

struct Rng(u64);
impl Rng {
    fn next(&mut self) -> u32 {
        self.0 ^= self.0 << 13;
        self.0 ^= self.0 >> 7;
        self.0 ^= self.0 << 17;
        (self.0 >> 16) as u32
    }
    fn below(&mut self, n: u32) -> u32 {
        self.next() % n
    }
    fn wchar(&mut self) -> u16 {
        match self.below(8) {
            0 => self.below(0x80) as u16,
            1 => 0x80 + self.below(0x80) as u16,
            2 => [0x20AC, 0x201A, 0x0192, 0x2026, 0x0160, 0x0152, 0x017D, 0x2122, 0x0178][self.below(9) as usize],
            3 => 0x2500 + self.below(0x80) as u16, // box drawing (CP437)
            4 => 0x3040 + self.below(0xC0) as u16, // kana
            5 => 0x4E00 + self.below(0x5200) as u16, // CJK
            6 => 0xFF00 + self.below(0x100) as u16, // fullwidth
            _ => self.next() as u16,
        }
    }
}

const CANARY_W: u16 = 0xCDCD;
const CANARY_B: u8 = 0xCD;

fn check_case_helpers(label: &str) {
    for c in 0..=0xFFFFu32 {
        let c = c as u16;
        unsafe {
            assert_eq!(port::RtlpUpcaseUnicodeChar(c), nref_RtlpUpcaseUnicodeChar(c), "{label} RtlpUpcase {c:#06x}");
            assert_eq!(port::RtlpDowncaseUnicodeChar(c), nref_RtlpDowncaseUnicodeChar(c), "{label} RtlpDowncase {c:#06x}");
            assert_eq!(port::RtlUpcaseUnicodeChar(c), nref_RtlUpcaseUnicodeChar(c), "{label} RtlUpcase {c:#06x}");
            assert_eq!(port::RtlDowncaseUnicodeChar(c), nref_RtlDowncaseUnicodeChar(c), "{label} RtlDowncase {c:#06x}");
        }
    }
    for b in 0..=0xFFu32 {
        let b = b as u8;
        unsafe { assert_eq!(port::RtlUpperChar(b), nref_RtlUpperChar(b), "{label} RtlUpperChar {b:#04x}") };
    }
    let (mut ra, mut ro, mut ca, mut co) = (0u16, 0u16, 0u16, 0u16);
    unsafe {
        port::RtlGetDefaultCodePage(&mut ra, &mut ro);
        nref_RtlGetDefaultCodePage(&mut ca, &mut co);
    }
    assert_eq!((ra, ro), (ca, co), "{label} RtlGetDefaultCodePage");
}

type ToWide = unsafe extern "system" fn(*mut u16, u32, *mut u32, *const u8, u32) -> i32;
type ToWideC = unsafe extern "C" fn(*mut u16, u32, *mut u32, *const u8, u32) -> i32;
type FromWide = unsafe extern "system" fn(*mut u8, u32, *mut u32, *const u16, u32) -> i32;
type FromWideC = unsafe extern "C" fn(*mut u8, u32, *mut u32, *const u16, u32) -> i32;

fn check_to_wide(label: &str, name: &str, r: ToWide, c: ToWideC, rng: &mut Rng) {
    for case in 0..4000 {
        let n = rng.below(24) as usize;
        let src: Vec<u8> = (0..n)
            .map(|_| if rng.below(3) == 0 { rng.below(0x80) as u8 } else { rng.next() as u8 })
            .collect();
        let out_bytes = rng.below(2 * n as u32 + 6);
        let with_rs = rng.below(4) != 0;
        let mut rb = vec![CANARY_W; out_bytes as usize / 2 + 2];
        let mut cb = rb.clone();
        let (mut rrs, mut crs) = (0xAAAA_AAAAu32, 0xAAAA_AAAAu32);
        let rrsp = if with_rs { &mut rrs as *mut u32 } else { std::ptr::null_mut() };
        let crsp = if with_rs { &mut crs as *mut u32 } else { std::ptr::null_mut() };
        let (rs, cs) = unsafe {
            (r(rb.as_mut_ptr(), out_bytes, rrsp, src.as_ptr(), n as u32), c(cb.as_mut_ptr(), out_bytes, crsp, src.as_ptr(), n as u32))
        };
        assert_eq!((rs, rrs, &rb), (cs, crs, &cb), "{label} {name} case {case}: src={src:02x?} out_bytes={out_bytes} rs={with_rs}");
    }
}

fn check_from_wide(label: &str, name: &str, r: FromWide, c: FromWideC, rng: &mut Rng) {
    for case in 0..4000 {
        let n = rng.below(24) as usize;
        let src: Vec<u16> = (0..n).map(|_| rng.wchar()).collect();
        // UnicodeSize in bytes, odd values included (the C halves it)
        let in_bytes = (2 * n as u32).saturating_sub(rng.below(2));
        let out = rng.below(2 * n as u32 + 4);
        let with_rs = rng.below(4) != 0;
        let mut rb = vec![CANARY_B; out as usize + 2];
        let mut cb = rb.clone();
        let (mut rrs, mut crs) = (0xAAAA_AAAAu32, 0xAAAA_AAAAu32);
        let rrsp = if with_rs { &mut rrs as *mut u32 } else { std::ptr::null_mut() };
        let crsp = if with_rs { &mut crs as *mut u32 } else { std::ptr::null_mut() };
        let (rs, cs) = unsafe {
            (r(rb.as_mut_ptr(), out, rrsp, src.as_ptr(), in_bytes), c(cb.as_mut_ptr(), out, crsp, src.as_ptr(), in_bytes))
        };
        assert_eq!((rs, rrs, &rb), (cs, crs, &cb), "{label} {name} case {case}: src={src:04x?} in_bytes={in_bytes} out={out} rs={with_rs}");
    }
}

fn check_sizes(label: &str, rng: &mut Rng) {
    for case in 0..4000 {
        let n = rng.below(24) as usize;
        let bytes: Vec<u8> = (0..n).map(|_| rng.next() as u8).collect();
        let wide: Vec<u16> = (0..n).map(|_| rng.wchar()).collect();
        let (mut a, mut b) = (0u32, 0u32);
        unsafe {
            let ra = port::RtlMultiByteToUnicodeSize(&mut a, bytes.as_ptr(), n as u32);
            let ca = nref_RtlMultiByteToUnicodeSize(&mut b, bytes.as_ptr(), n as u32);
            assert_eq!((ra, a), (ca, b), "{label} RtlMultiByteToUnicodeSize case {case}: {bytes:02x?}");
            let ra = port::RtlUnicodeToMultiByteSize(&mut a, wide.as_ptr(), 2 * n as u32);
            let ca = nref_RtlUnicodeToMultiByteSize(&mut b, wide.as_ptr(), 2 * n as u32);
            assert_eq!((ra, a), (ca, b), "{label} RtlUnicodeToMultiByteSize case {case}: {wide:04x?}");
        }
    }
}

fn check_custom_cp(label: &str, rt: &mut NLSTABLEINFO, ct: &mut NLSTABLEINFO, rng: &mut Rng) {
    // Single-byte custom code pages only: the C's DBCS branches are ASSERT(FALSE) stubs.
    if rt.OemTableInfo.DBCSCodePage != 0 {
        return;
    }
    for case in 0..2000 {
        let n = rng.below(24) as usize;
        let wide: Vec<u16> = (0..n).map(|_| rng.wchar()).collect();
        let bytes: Vec<i8> = (0..n).map(|_| rng.next() as i8).collect();
        let out = rng.below(2 * n as u32 + 4);
        unsafe {
            let (mut rb, mut cb) = (vec![CANARY_W; out as usize / 2 + 2], vec![CANARY_W; out as usize / 2 + 2]);
            let (mut rrs, mut crs) = (0u32, 0u32);
            let r = port::RtlCustomCPToUnicodeN(&mut rt.OemTableInfo, rb.as_mut_ptr(), out, &mut rrs, bytes.as_ptr(), n as u32);
            let c = nref_RtlCustomCPToUnicodeN(&mut ct.OemTableInfo, cb.as_mut_ptr(), out, &mut crs, bytes.as_ptr(), n as u32);
            assert_eq!((r, rrs, &rb), (c, crs, &cb), "{label} RtlCustomCPToUnicodeN case {case}");
            let mut w1 = wide.clone();
            let mut w2 = wide.clone();
            let (mut rb, mut cb) = (vec![CANARY_B as i8; out as usize + 2], vec![CANARY_B as i8; out as usize + 2]);
            let r = port::RtlUnicodeToCustomCPN(&mut rt.OemTableInfo, rb.as_mut_ptr(), out, &mut rrs, w1.as_mut_ptr(), 2 * n as u32);
            let c = nref_RtlUnicodeToCustomCPN(&mut ct.OemTableInfo, cb.as_mut_ptr(), out, &mut crs, w2.as_mut_ptr(), 2 * n as u32);
            assert_eq!((r, rrs, &rb), (c, crs, &cb), "{label} RtlUnicodeToCustomCPN case {case}");
            let r = port::RtlUpcaseUnicodeToCustomCPN(&mut rt.OemTableInfo, rb.as_mut_ptr(), out, &mut rrs, w1.as_mut_ptr(), 2 * n as u32);
            let c = nref_RtlUpcaseUnicodeToCustomCPN(&mut ct.OemTableInfo, cb.as_mut_ptr(), out, &mut crs, w2.as_mut_ptr(), 2 * n as u32);
            assert_eq!((r, rrs, &rb), (c, crs, &cb), "{label} RtlUpcaseUnicodeToCustomCPN case {case}");
        }
    }
}

fn run(label: &str, ansi: &str, oem: &str) {
    let dir = env!("RTL_DIFFTEST_NLS_DIR");
    let case = env!("RTL_DIFFTEST_CASE_NLS");
    // Each side gets its own copy of the tables: a write through a stray pointer would
    // otherwise be invisible to the comparison.
    let (ra, ro, rc) = (table(&format!("{dir}/{ansi}.nls")), table(&format!("{dir}/{oem}.nls")), table(case));
    let (ca, co, cc) = (table(&format!("{dir}/{ansi}.nls")), table(&format!("{dir}/{oem}.nls")), table(case));
    let mut rt: NLSTABLEINFO = zeroed();
    let mut ct: NLSTABLEINFO = zeroed();
    unsafe {
        port::RtlInitNlsTables(ra, ro, rc, &mut rt);
        port::RtlResetRtlTranslations(&mut rt);
        nref_RtlInitNlsTables(ca, co, cc, &mut ct);
        nref_RtlResetRtlTranslations(&mut ct);
        assert_eq!(std::ptr::addr_of!(port::NlsMbCodePageTag).read(), (ansi == "c_932") as u8, "{label}: ANSI DBCS tag");
    }
    let mut rng = Rng(0x9E37_79B9_7F4A_7C15 ^ label.len() as u64);
    check_case_helpers(label);
    check_to_wide(label, "RtlMultiByteToUnicodeN", port::RtlMultiByteToUnicodeN, nref_RtlMultiByteToUnicodeN, &mut rng);
    check_to_wide(label, "RtlOemToUnicodeN", port::RtlOemToUnicodeN, nref_RtlOemToUnicodeN, &mut rng);
    check_from_wide(label, "RtlUnicodeToMultiByteN", port::RtlUnicodeToMultiByteN, nref_RtlUnicodeToMultiByteN, &mut rng);
    check_from_wide(label, "RtlUnicodeToOemN", port::RtlUnicodeToOemN, nref_RtlUnicodeToOemN, &mut rng);
    check_from_wide(label, "RtlUpcaseUnicodeToMultiByteN", port::RtlUpcaseUnicodeToMultiByteN, nref_RtlUpcaseUnicodeToMultiByteN, &mut rng);
    check_from_wide(label, "RtlUpcaseUnicodeToOemN", port::RtlUpcaseUnicodeToOemN, nref_RtlUpcaseUnicodeToOemN, &mut rng);
    check_sizes(label, &mut rng);
    check_custom_cp(label, &mut rt, &mut ct, &mut rng);
}

// One test: both sides keep their NLS state in process globals.
#[test]
fn nls_c_vs_table_driven_port() {
    run("1252/437", "c_1252", "c_437");
    run("932/932", "c_932", "c_932");
    // And the OEM side is really CP437, not the model: U+2554 (box drawing) is 0xC9 there.
    let mut b = [0u8; 1];
    let w = [0x2554u16];
    run("1252/437 again", "c_1252", "c_437");
    unsafe { port::RtlUnicodeToOemN(b.as_mut_ptr(), 1, std::ptr::null_mut(), w.as_ptr(), 2) };
    assert_eq!(b[0], 0xC9);
}
